    CScriptThing hero;
    void NewScriptFrame() { ++frames; logs("f"); }
    bool StartScriptingEntity(const CScriptThing&, CHandle&, int priority) { logs(priority == 4 ? "S" : "?"); return startFailures-- <= 0; }
